INSERT INTO daihon_decks (title, subtitle, speaker, intro, sort_order, created_by) SELECT '東京タクシーセンター 知識集', '2026年10月11日時点の東京タクシーセンターWebサイトより', '', '東京タクシーセンターのWebサイトから、業務で使える情報をカテゴリー別にまとめた知識集。各スライドの下のボタンから元のページを開ける。', COALESCE(MAX(sort_order), -1) + 1, 'system' FROM daihon_decks;
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 0, 'cover', 'blue', '東京タクシーセンター 知識集', '2026年10月11日時点の東京タクシーセンターWebサイトより', '業務で使える情報をカテゴリーごとにまとめました' || char(10) || 'スライド下のボタンから、元のページをそのまま開けます', 'この台本は、東京タクシーセンターのWebサイトにある情報のうち、タクシーの仕事で使えるものをまとめた知識集です。情報は変わることがあるので、最新はスライド下のボタンから元のページで確認してください。', '[]', '', '', '東京タクシーセンター トップ｜https://www.tokyo-tc.or.jp/' || char(10) || '事業者・運転者の皆様｜https://www.tokyo-tc.or.jp/driver/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 1, 'steps', 'blue', 'カテゴリー', 'この知識集の中身', 'センターと登録｜運転者証・試験・手続き' || char(10) || '研修｜新人向け・UD・英語' || char(10) || '乗り場｜羽田・東京駅・優良・EV・銀座' || char(10) || '現場の声｜警察・住民からの要望とトラブル事例' || char(10) || 'お客様対応｜忘れ物・苦情・表彰・評価', '最後に「最新のお知らせ」と「教材・リンク集」もあります。一覧で見たいときは、別の台本「知識集 まとめ（早見表）」を開いてください。', '[]', '', '', '');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 2, 'section', 'blue', '東京タクシーセンターと登録', 'タクシーの仕事のスタート地点', '', '', '[]', '', '', '');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 3, 'content', 'blue', '東京タクシーセンターとは', 'タクシー業務適正化特別措置法にもとづく「適正化事業実施機関」', '運転者の登録（運転者証の交付）' || char(10) || '試験・研修（新規講習など）' || char(10) || '街頭での指導（乗車拒否や乗り場ルール違反の防止）' || char(10) || 'タクシー乗り場の設置・運営' || char(10) || 'お客様からの苦情・要望の受付' || char(10) || '優良運転者の表彰・会社の評価制度' || char(10) || '■ 所在地：江東区南砂7-3-3（代表 03-3648-5131）', '指導する側であり、守ってくれる側でもある団体です。新規講習で一度行っている人も多いと思います。', '[]', '', '', '業務のご紹介｜https://www.tokyo-tc.or.jp/center/business/' || char(10) || 'アクセス｜https://www.tokyo-tc.or.jp/center/access/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 4, 'stat', 'blue', '数字で見る東京のタクシー運転者', '令和8年8月末', '6.7万人｜法人の登録運転者 67,486人（うち女性2,675人）' || char(10) || '55.5歳｜法人の登録運転者の平均年齢' || char(10) || '8,460｜個人タクシーの事業者（平均63.7歳）', '平均55歳の業界なので、20代の新卒は本当に貴重な存在です。', '[]', '', '', '業務のご紹介（登録者数）｜https://www.tokyo-tc.or.jp/center/business/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 5, 'content', 'blue', '運転者証は「表示しないと営業できない」', 'タクシー業務適正化特別措置法 第13条', '23区・武蔵野市・三鷹市の法人タクシー運転者は、センターへの登録が義務' || char(10) || '運転者証を車内（前面ガラスの内側）に表示しないと営業できない' || char(10) || '■ 羽田空港で「運転者証の不表示」が増えているとセンターから注意喚起' || char(10) || '**乗務前に必ず確認**', '車を乗り換えたときに付け忘れる人が多いです。出庫前の点検項目に入れておきましょう。', '[]', '', '', '登録手続きについて｜https://www.tokyo-tc.or.jp/driver/register/' || char(10) || '運転者証不表示の増加（羽田）｜https://www.tokyo-tc.or.jp/instance/instruction/000205/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 6, 'content', 'blue', '登録の手続き（会社を通して行うもの）', '運転者証・登録事項の変更', '新規登録：手数料 3,740円（写真1枚）' || char(10) || '住所変更：手数料なし（住民票の写しが必要）' || char(10) || '氏名変更・有効期限の変更：1,210円' || char(10) || '会社を移るとき：1,870円（前の会社から運転者証が返納されてから）' || char(10) || '運転者証をなくした・壊した：再交付 1,870円（理由書が必要）' || char(10) || '■ 受付：平日 9時〜16時（月曜は混むので避ける）', '引っ越したら住所変更の届出が必要です。会社の管理者に伝えてください。', '[]', '', '', '登録手続きについて｜https://www.tokyo-tc.or.jp/driver/register/' || char(10) || '登録窓口の混雑状況（YouTube）｜https://www.youtube.com/@公益財団法人東京タクシー/live');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 7, 'content', 'blue', '登録が消えてしまうとき', '消除されたら、また新規登録からやり直し', '登録の取消処分を受けた' || char(10) || '**40日以上の免許停止、または免許取消**' || char(10) || '運転者証を返納してから2年たった' || char(10) || '運転免許証が失効した' || char(10) || '本人が消除を申請した', '交通違反の累積で免停が40日以上になると、タクシーの登録も消えます。安全運転は仕事そのものを守ることです。', '[]', '', '', '登録の消除について｜https://www.tokyo-tc.or.jp/driver/register/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 8, 'content', 'blue', '申請用の写真', '自分で用意するときの決まり', '縦6cm × 横4cm、6か月以内に撮影' || char(10) || '無帽・正面・無背景、顔の大きさ3cm以上' || char(10) || '裏に氏名と撮影日を書く' || char(10) || '家で印刷するなら写真用の光沢紙に' || char(10) || '■ センター内の写真室：1枚1,000円／2枚1,200円（平日9〜17時）', '', '[]', '', '', '申請用写真について｜https://www.tokyo-tc.or.jp/driver/register/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 9, 'stat', 'blue', '「輸送の安全及び利用者の利便の確保に関する試験」', 'タクシー運転者になるための試験', '45問｜筆記試験（法令・安全・接遇）' || char(10) || '36問｜以上の正解で合格（正答率80％）' || char(10) || '2年｜合格証の有効期限' || char(10) || '■ 地理の科目は令和6年2月に廃止。新規講習3日目に地理の効果測定あり' || char(10) || '■ 一般受験・再試験：月・火・金曜（手数料3,400円）', 'みなさんは合格済みのはずですが、後輩に聞かれたときのために。', '[]', '', '', '試験のご案内｜https://www.tokyo-tc.or.jp/driver/geography/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 10, 'question', 'blue', '運転免許の停止が何日以上になると、タクシーの登録が消える？', '', '30日以上' || char(10) || '40日以上' || char(10) || '90日以上', '登録が消える条件の確認です。', '[]', '', '{"answer": 1, "points": 10, "time": 20, "phone": false}', '');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 11, 'answer', 'blue', '40日以上', '登録の消除', '40日以上の免停・免許取消で登録は消除' || char(10) || '戻るときは新規登録と同じ手続き（試験・講習から）', '', '[]', '', '', '登録の消除について｜https://www.tokyo-tc.or.jp/driver/register/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 12, 'section', 'green', '研修・検定', 'センターで受けられる研修', '', '', '[]', '', '', '');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 13, 'content', 'green', '研修の種類', '会社から申し込むものが基本', '新規講習（3日）：新しく運転者になる人' || char(10) || '新人特別接遇研修（1日）：若い運転者向けのマナー・コミュニケーション' || char(10) || '自主UD研修（1〜2日）：高齢の方・障がいのある方への対応、車いす' || char(10) || '外国人旅客接遇研修（半日）：英語・中国語' || char(10) || '適正化研修（1日）：違反などで必要と認められた人' || char(10) || '命令講習・命令研修：処分を受けた人', '「適正化研修」は違反をした人が受ける研修です。受けずに済むようにしましょう。', '[]', '', '', '研修・検定について｜https://www.tokyo-tc.or.jp/driver/training/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 14, 'content', 'green', '新人特別接遇研修', '若い世代の運転者のための1日研修', '19歳から二種免許が取れるようになり、若い運転者が増えた' || char(10) || '外部講師から社会人マナー・コミュニケーションを学ぶ' || char(10) || '■ 内容' || char(10) || 'アイスブレイク・傾聴力・クレームにならない対応' || char(10) || 'CS（顧客満足）・CD（顧客感動）・CX（顧客体験）' || char(10) || '実際の苦情事例・乗り場や共同施設の説明' || char(10) || '■ 研修費 2,200円（会社経由で申し込み）', 'まさに新卒のための研修です。受けたい人は会社に相談してください。', '[]', '', '', '新人特別接遇研修｜https://www.tokyo-tc.or.jp/driver/training/sp-hospitality-training/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 15, 'content', 'green', '自主UD研修（ユニバーサルドライバー）', '火・木・金に実施', 'お客様とのコミュニケーションの留意点' || char(10) || '接遇・介助の留意点' || char(10) || '車いすの扱い方、UD車両（JPNタクシー）への乗り降り' || char(10) || '■ 東京観光タクシードライバー認定の要件の一つ' || char(10) || '■ 会社の評価制度で加点される' || char(10) || '■ 盲導犬UD研修の回もある', '車椅子の練習会とあわせて、UD研修も受けておくと自信になります。', '[]', '', '', '自主UD研修｜https://www.tokyo-tc.or.jp/driver/training/universal-driver/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 16, 'content', 'green', '外国人旅客接遇研修（英語・中国語）', '半日。希望者が殺到中', '英語 初級・中級：マナーと文化の違い、基本の会話、ロールプレイ' || char(10) || '英語 上級：中級修了者向け。緊急時（パスポート紛失など）の対応' || char(10) || 'EXCELLENT観光コース：上級修了者向け。観光案内' || char(10) || '中国語 入門編' || char(10) || '■ 修了すると羽田の「おもてなしレーン」に入れる（修了証の携帯と入構表示板が必要）' || char(10) || '■ 研修費 4,120円', '羽田で稼ぎたいなら、まずこの研修です。', '[]', '', '', '外国人旅客接遇研修｜https://www.tokyo-tc.or.jp/driver/training/en-hospitality-training/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 17, 'content', 'green', 'ENGLISH CERTIFIED DRIVER（ECD）', '英語で接客できる運転者の認定', '英語上級とUD研修を修了 → 外国人旅客接遇英語検定に合格' || char(10) || '検定：挨拶・自己紹介（1〜2分）＋ 乗車を想定したロールプレイ（5〜6分）' || char(10) || '合格するとECD認定章を車体に貼る' || char(10) || '■ 羽田第3待機所のECDレーン、東京駅八重洲口の検定合格者レーンに入れる' || char(10) || '■ 合格者の名前はセンターのWebサイトで公表される', '', '[]', '', '', 'ENGLISH CERTIFIED DRIVER｜https://www.tokyo-tc.or.jp/passenger/english-certified-driver/' || char(10) || '外国人旅客接遇英語検定｜https://www.tokyo-tc.or.jp/driver/training/en-hospitality-exam/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 18, 'question', 'green', '羽田空港の「おもてなしレーン」に入るために必要なのは？', '', '英語検定の合格' || char(10) || '外国人旅客接遇研修（英語）の修了' || char(10) || '優良運転者表彰', 'ECDレーンと混ざりやすいところです。', '[]', '', '{"answer": 1, "points": 10, "time": 20, "phone": false}', '');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 19, 'answer', 'green', '外国人旅客接遇研修（英語）の修了', '修了証を持ち、入構表示板を出す', 'おもてなしレーン：研修の修了でOK' || char(10) || 'ECDレーン：さらに英語検定の合格とECD認定章が必要', '', '[]', '', '', '羽田空港タクシー乗り場のご案内｜https://www.tokyo-tc.or.jp/driver/stand/haneda-stand/');
