INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 21, 'content', 'slate', '羽田空港の乗り場の基本', 'すべての乗り場が「定額運賃乗り場」', '定額ゾーンへの申し込みは自動で定額（お客様が断った場合を除く）' || char(10) || 'ナンバー末尾の規制：奇数日＝奇数、偶数日＝偶数（第5優良乗り場は除く）' || char(10) || '定額運賃表を後部座席から見える所に・ETC車・WELCOME ABOARD！ステッカー' || char(10) || '世田谷区の一部は一般道の方が安いことがある → 首都高か一般道かを確認' || char(10) || '■ 第3ターミナルの神奈川乗り場は令和8年2月1日〜令和9年1月31日 休止中', '', '[]', '', '', '羽田空港タクシー乗り場のご案内｜https://www.tokyo-tc.or.jp/driver/stand/haneda-stand/' || char(10) || '羽田空港 繁忙期の運営方法（R8年度）｜https://www.tokyo-tc.or.jp/news/uploads/haneda2026.pdf');
