INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 26, 'figure', 'slate', '羽田空港 第3・第4タクシー待機所', '優良乗り場の資格がない車は入れない', '英語・中級以上の修了証を持ち、入構表示板を出す' || char(10) || 'ECDレーン（2列38台）：検定合格証とECD認定章' || char(10) || 'ワゴンレーン（2列38台）' || char(10) || '第3へは必ず第4を経由（環八を大鳥居方向から左折）' || char(10) || '末尾番号の規制は除外', '', '["daihon/ttc/ttc_haneda_pool34.jpg"]', '', '', '羽田空港タクシー乗り場のご案内｜https://www.tokyo-tc.or.jp/driver/stand/haneda-stand/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 27, 'figure', 'slate', '第3・第4タクシー乗り場への経路', '令和7年5月12日から第3乗り場への入路が変更', '', '', '["daihon/ttc/ttc_haneda_route.jpg"]', '', '', '第3乗り場への入路変更（PDF）｜https://www.tokyo-tc.or.jp/news/uploads/2025_0512_haneda_route3.pdf');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 28, 'content', 'slate', '「ワゴンタクシー」の決まり', '羽田・東京駅のワゴンレーンに入れる車', '車検証の車体の形が「ステーションワゴン」で、次のどちらか' || char(10) || 'スーツケース（72×52×25cm）が2個以上トランクに入る' || char(10) || '乗車定員7名以上で、お客様が6名以上乗れる' || char(10) || '■ 主な車種：オデッセイ、プリウスα、NV200、ハイエース、アルファード、ヴェルファイア、エルグランドなど', '', '[]', '', '', '羽田空港タクシー乗り場のご案内｜https://www.tokyo-tc.or.jp/driver/stand/haneda-stand/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 29, 'figure', 'slate', '東京駅八重洲口前タクシー乗り場', '優良乗り場。5台同時に乗車', '第1〜5レーン：一般・UD（31台）' || char(10) || '第6レーン：検定合格者・ワゴン（7台）' || char(10) || '優良乗り場の資格が必要' || char(10) || '検定合格者レーンは合格証とECD認定章（ワゴン車は除く）', '', '["daihon/ttc/ttc_yaesu.jpg"]', '', '', '東京駅八重洲口前タクシー乗り場のご案内｜https://www.tokyo-tc.or.jp/driver/stand/yaesu-stand/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 30, 'content', 'slate', '待機状況をライブで見られる', '羽田・東京駅の待機所の混み具合', '羽田 第1待機所・第3/4待機所・第4乗り場・第5優良乗り場' || char(10) || '東京駅八重洲口前の乗り場・待機所' || char(10) || '羽田は1分ごと、東京駅は約30秒ごとに更新' || char(10) || '**走行中に見るのは道路交通法違反。必ず安全な場所に停めてから**', '空港に向かうか迷ったとき、停車中に確認すると無駄な待ちが減らせます。', '[]', '', '', '羽田 第1待機所｜https://ttc.taxi-inf.jp/index.php' || char(10) || '羽田 第3・4待機所｜https://ttc.taxi-inf.jp/no23.php' || char(10) || '羽田 第5優良乗り場｜https://ttc.taxi-inf.jp/No5TaxiStand.php' || char(10) || '東京駅八重洲口｜https://svc01.p-counter.jp/doc-server-taxi/tokyo_taxi/yaesu_taxi_info.html');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 31, 'figure', 'slate', '優良タクシー乗り場 15地区28か所', '令和8年4月3日から恵比寿駅西口前・北千住駅西口前が追加', '入れる車：優良運転者章／優良AAA・AA・Aの会社で優良表示／個人のマスター ＋ ステッカー' || char(10) || '休止中：渋谷駅西口前・品川駅西口前' || char(10) || '空車不足のときだけ一般車も入れる', 'ハンドブックは13地区26か所ですが、今は増えています。', '["daihon/ttc/ttc_yuryo_map.jpg"]', '', '', '優良タクシー乗り場のご案内｜https://www.tokyo-tc.or.jp/driver/stand/superior-stand/');
