INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 34, 'content', 'slate', 'T-CAT優良乗り場が移動中', '令和8年10月6日から、先頭位置を約10m後方へ', '中央区日本橋箱崎町42' || char(10) || '施設側の都合による一時移設' || char(10) || '■ T-CAT裏の道路での長時間駐車・交差点内の駐車は警察からも注意喚起', '', '[]', '', '', 'T-CAT優良乗り場の一時移設｜https://www.tokyo-tc.or.jp/news/driver/000977/' || char(10) || '久松警察署からのお願い｜https://www.tokyo-tc.or.jp/instance/demand/000693/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 35, 'figure', 'slate', 'EV・HVタクシー乗り場', '新丸ビル前（千代田区丸の内1-5）平日9時〜21時', '電気自動車・ハイブリッド車だけが入れる（原則禁煙車）' || char(10) || '左側の客席ドアに専用ステッカーを貼る' || char(10) || '運用時間外・土日祝は一般の乗り場' || char(10) || '空車があふれたら大丸有地区の他の乗り場か流しへ', '', '["daihon/ttc/ttc_ev2.jpg", "daihon/ttc/ttc_ev1.jpg"]', '', '', 'EV・HVタクシー乗り場のご案内｜https://www.tokyo-tc.or.jp/driver/stand/ev-stand/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 36, 'figure', 'slate', '銀座の乗車禁止地区（2026年版の地図）', '平日 22時〜翌1時は乗り場以外で乗せられない', '土・日・祝日・休日は除く（お盆・年末もカレンダー通り）' || char(10) || '乗り場以外で申し込まれたら、銀座タクシー乗り場リーフレットで説明' || char(10) || '**リーフレットの携行が銀座に入る条件**', '', '["daihon/ttc/ttc_ginza_map.jpg"]', '', '', '銀座乗車禁止地区のご案内｜https://www.tokyo-tc.or.jp/driver/stand/prohibit-ginza/' || char(10) || '銀座乗り場リーフレット（PDF）｜https://www.tokyo-tc.or.jp/download/applicationform/ginza_leaflet_2021_0624.pdf');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 37, 'content', 'slate', '銀座1号乗り場のショットガンシステム', '築地川第一駐車場をプールにして順番に送る仕組み', '入構には登録が必要（会社単位）' || char(10) || '駐車場出口のゲートバーは1台ずつ通過（バー破損・事故に注意）' || char(10) || '入構ルールは「運転者の皆様へ」のPDFで確認', '', '[]', '', '', '銀座ショットガンシステムについて｜https://www.tokyo-tc.or.jp/driver/ginza-sg/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 38, 'figure', 'slate', '六本木交差点周辺（2026年版）', '終日 客待ち禁止・入路指定', '交差点とギラギラ舗装は客待ち禁止（カメラ映像でも指導）' || char(10) || 'アルカトーレ前・六本木ビル前の乗り場は首都高高架下のプール経由' || char(10) || '**アルカトーレ前の待機枠は3台。はみ出し待機に警察へ苦情**', '', '["daihon/ttc/ttc_roppongi.jpg"]', '', '', '規制地区一覧｜https://www.tokyo-tc.or.jp/driver/regulation-area/' || char(10) || '麻布警察署からの申告｜https://www.tokyo-tc.or.jp/instance/demand/000273/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 39, 'content', 'slate', '規制地区・自主規制の一覧はここ', '行く前に必ず確認', '■ 適正運営推進制度の規制地区' || char(10) || '東京駅八重洲口・銀座1〜11号・花椿通り・新幸橋・内幸町・みゆき通り・六本木・優良乗り場' || char(10) || '■ 自主規制' || char(10) || '羽田空港・吉祥寺駅北口・池袋駅東口・池袋駅西口' || char(10) || '■ 地区名をクリックすると地図が出る', '', '[]', '', '', '規制地区一覧｜https://www.tokyo-tc.or.jp/driver/regulation-area/' || char(10) || '自主規制一覧表｜https://www.tokyo-tc.or.jp/driver/self-restraint-area/' || char(10) || '乗り場案内｜https://www.tokyo-tc.or.jp/driver/stand/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 40, 'content', 'slate', '広告付タクシーシェルター', '屋根・ベンチ付きの乗り場（29か所）', '青山OMスクエア前・三田国際ビル前・コレド日本橋前・山王パークタワー前' || char(10) || '代々木駅西口・ベルビー赤坂・大塚駅北口・五反田駅西口・大井町駅西口' || char(10) || '赤坂アビタシオン・竹芝駅・アークヒルズ・虎の門三井ビル・飯野ビル' || char(10) || '御茶ノ水ソラシティ・東京証券会館・松屋浅草東側・松坂屋上野店 ほか' || char(10) || '■ 5か所はデジタルサイネージで交通・気象情報も表示', '屋根付きの乗り場はお客様が並びやすく、雨の日に強い付け待ち場所になります。', '[]', '', '', '広告付タクシーシェルターのご案内｜https://www.tokyo-tc.or.jp/driver/stand/ad-taxi/');
