INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 42, 'content', 'amber', '「運転手が乗っていても駐車違反です」', '警視庁（霞が関2-1・2-2周辺）令和8年6月', '午後9時〜午前3時すぎ、個人タクシー中心に客待ちの長い列' || char(10) || '110番通報が頻繁 → パトカーが来ても、いなくなると元通り' || char(10) || '**客待ちはタクシー乗り場で**' || char(10) || '苦情が続けば取締りを強化する', '「車内にいれば大丈夫」は間違いです。非放置車両として取り締まられます。', '[]', '', '', '警視庁からの注意喚起｜https://www.tokyo-tc.or.jp/instance/demand/000867/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 43, 'content', 'amber', '交差点・横断歩道・ロータリーに止めない', '池袋・錦糸町・新小岩・新橋・田園調布', '池袋駅周辺：交差点内や横断歩道上での客待ち・乗降 → 取締り強化' || char(10) || '錦糸町駅南口：ロータリー内・京葉道路に駐車 → 待機所は2列で' || char(10) || '新小岩駅：待機所からあふれた車が横断歩道上に停車' || char(10) || 'ニュー新橋ビル前：直近の交差点での客待ちを取締り' || char(10) || '田園調布駅東口：実車で転回して横断歩道上に停車', '交差点や横断歩道は「止まってはいけない場所」です。お客様を乗せ降ろしするのもNGです。', '[]', '', '', '池袋警察署（交差点内）｜https://www.tokyo-tc.or.jp/instance/demand/000361/' || char(10) || '本所警察署（錦糸町）｜https://www.tokyo-tc.or.jp/instance/demand/000441/' || char(10) || '葛飾警察署（新小岩）｜https://www.tokyo-tc.or.jp/instance/demand/000632/' || char(10) || '新橋の取締り強化｜https://www.tokyo-tc.or.jp/instance/demand/000274/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 44, 'content', 'amber', '待機所・乗り場の使い方', 'あふれたら路上で待たない', '池袋駅東口：乗り場が空いていないのに見切り発進 → 出口のモニターで空きを確認' || char(10) || '綾瀬駅東口：待機所を使わずロータリー内に駐車 → バスの妨げ' || char(10) || '竹ノ塚駅西口・新小岩駅南口：待機枠をはみ出して身障者用乗降スペースをふさぐ' || char(10) || '**待機所は休憩所ではない**（弁当・テレビ・車外で喫煙して、お客様を待たせた苦情）', '待機所で前の車が動かないとき、お客様は乗り場で待っています。すぐ出られる状態で並びましょう。', '[]', '', '', '池袋警察署（東口待機所）｜https://www.tokyo-tc.or.jp/instance/demand/000360/' || char(10) || '綾瀬駅東口｜https://www.tokyo-tc.or.jp/instance/trouble/000475/' || char(10) || '竹ノ塚駅西口｜https://www.tokyo-tc.or.jp/instance/demand/000727/' || char(10) || '待機所について（苦情）｜https://www.tokyo-tc.or.jp/instance/trouble/000257/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 45, 'question', 'amber', '乗り場の手前の身障者用乗降スペースに車が止まろうとしている。クラクションで知らせていい？', '', '知らせていい' || char(10) || '鳴らしてはいけない', '新小岩駅南口で実際に区役所から寄せられた要望です。', '[]', '', '{"answer": 1, "points": 10, "time": 20, "phone": false}', '');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 46, 'answer', 'amber', '鳴らしてはいけません', '葛飾区役所からのお願い（新小岩駅南口）', 'クラクションは「鳴らせ」の標識がある場所、見通しの悪い所、危険を防ぐためやむを得ないとき以外は鳴らせない（道路交通法）' || char(10) || '身障者用乗降スペースは使う人のための場所', '', '[]', '', '', '葛飾区役所からのお願い｜https://www.tokyo-tc.or.jp/instance/demand/000775/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 47, 'content', 'amber', '喫煙とごみ', 'エッセンシャルワーカーとして見られている', '田端小学校前：駐車禁止の場所で路上喫煙、横を小学生が通っている' || char(10) || '台東区 田原公園：路上駐車しながら喫煙（台東区は朝7〜9時は路上喫煙禁止）' || char(10) || '世田谷区 等々力：一方通行路に駐車して喫煙（世田谷区は指定場所以外は禁煙）' || char(10) || '青山公園の調整待機所：ごみ箱の上にごみを置いていく → 環境美化運動を実施' || char(10) || '■ 喫煙は喫煙できる場所で。ごみは持ち帰るか、ごみ箱の中へ', '1人のマナー違反で、調整待機所そのものが使えなくなることもあります。', '[]', '', '', '路上喫煙について（田端）｜https://www.tokyo-tc.or.jp/instance/trouble/000187/' || char(10) || '台東区役所（田原公園）｜https://www.tokyo-tc.or.jp/instance/demand/000831/' || char(10) || '世田谷区 等々力｜https://www.tokyo-tc.or.jp/instance/demand/000765/' || char(10) || '青山調整待機所の環境美化｜https://www.tokyo-tc.or.jp/news/center/000978/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 48, 'content', 'amber', 'ここで降ろさない・ここに入らない', '施設や地域からのお願い', '東京駅 日本橋口の駅前広場：乗り入れは降車のみ。客待ちはしない（八重洲側・丸の内側の乗り場へ）' || char(10) || '東京ステーションホテルの車寄せ（丸の内南口）：ホテル利用者以外は降ろさない' || char(10) || '高田馬場3-37と3-38の間：自動車通行止め。抜け道に使わない' || char(10) || '羽田空港第3待機所：決められた入路で入る', '「近いからここで」と降ろすと、施設の方に迷惑がかかります。迷ったら一言確認しましょう。', '[]', '', '', 'JR東日本より（日本橋口）｜https://www.tokyo-tc.or.jp/instance/trouble/000207/' || char(10) || '東京ステーションホテルより｜https://www.tokyo-tc.or.jp/instance/trouble/000474/' || char(10) || '戸塚警察署（高田馬場）｜https://www.tokyo-tc.or.jp/instance/demand/000620/' || char(10) || '入路を守らない（羽田）｜https://www.tokyo-tc.or.jp/instance/trouble/000262/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 49, 'content', 'amber', '走り方を見られている', 'タクシー全般への苦情と警察からのお願い', '交差点内やバス停で客待ち、ウインカーを出さずに急に左へ寄る → 「プロの模範になって」' || char(10) || '歌舞伎町周辺：違法駐車・酔った歩行者とのトラブルが増加' || char(10) || '酔って路上に寝ている人をひく重大事故 → **午後4時から早めのライト・ハイビームの活用**' || char(10) || 'ダイヤマーク（◇）の先は横断歩道 → 減速して歩行者に注意', 'お客様を見つけて急に左に寄るのが、いちばん事故と苦情につながります。', '[]', '', '', 'タクシー全般について｜https://www.tokyo-tc.or.jp/instance/trouble/000208/' || char(10) || '新宿警察署より｜https://www.tokyo-tc.or.jp/instance/trouble/000212/' || char(10) || 'ダイヤマークって何？｜https://www.tokyo-tc.or.jp/instance/demand/000241/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 50, 'content', 'amber', '営業のヒントになる声', 'お客様からの要望', '「中原街道で平日朝の通勤時間に空車が全然来ない」' || char(10) || 'お客様が困っている場所は、空車が足りていない場所' || char(10) || '■ 情報提供のページには、こうした声が随時のる', 'クレームの裏には需要があります。こういう情報は売上につながります。', '[]', '', '', '空車が来ない｜https://www.tokyo-tc.or.jp/instance/trouble/000265/' || char(10) || '情報提供（一覧）｜https://www.tokyo-tc.or.jp/instance/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 51, 'section', 'green', 'お客様対応の知識', '忘れ物・苦情・表彰・評価', '', '', '[]', '', '', '');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 52, 'content', 'green', '忘れ物を聞かれたら', 'センターでは忘れ物を扱っていない', '領収書や配車アプリで会社が分かる → その会社へ' || char(10) || '会社が分からない → 最寄りの警察署・交番へ届け出' || char(10) || '車内の忘れ物は、会社で保管したあと警察署へ届けられる' || char(10) || '警視庁の「拾得物公表システム」で都内の落とし物を検索できる' || char(10) || '■ 無線グループごとの忘れ物専用電話もある', 'お客様に聞かれたら「領収書の会社に連絡してください」と案内しましょう。', '[]', '', '', 'タクシー乗車時の忘れ物について｜https://www.tokyo-tc.or.jp/passenger/lostandfound/' || char(10) || '警視庁 拾得物公表システム｜https://www.keishicho.metro.tokyo.lg.jp/sodan/otoshimono/kensaku.html');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 53, 'content', 'green', '苦情はこうして届く', 'センターの申告フォーム', '実名苦情：調査して会社・運転者を指導、結果を回答（2週間前後）' || char(10) || '匿名苦情：会社に通報のみ' || char(10) || '善行：お褒めの言葉・人命救助など → 会社に伝わる' || char(10) || '対象は23区・武蔵野市・三鷹市の会社の車' || char(10) || '■ あおり運転などの道路交通法、運賃返金などの民事は対象外', '良いことをすれば「善行」として会社に届きます。苦情だけの仕組みではありません。', '[]', '', '', '苦情・要望の受付｜https://www.tokyo-tc.or.jp/passenger/complaint/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 54, 'content', 'green', '優良運転者表彰', 'まじめに続けた人が表彰される', '一般（5年）・10年・20年・30年・特別（40年）' || char(10) || '例：5年表彰 → 過去5年 違反なし、過去3年 事故・交通違反なし' || char(10) || '乗り場ルール違反の点数が2点以下' || char(10) || '受賞すると「優良表示証」→ 優良乗り場に入れる' || char(10) || '■ これまでの受賞者は42,402人', '5年後、みなさんも表彰を目指せます。優良乗り場に入れるのは大きいです。', '[]', '', '', '表彰について｜https://www.tokyo-tc.or.jp/driver/commend/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 55, 'content', 'green', 'タクシー評価制度（会社の評価）', '運転者ではなく「会社」の評価', '「接客・サービス」「安全・運行管理」「経営姿勢」＋加点 = 100点満点' || char(10) || '優良AAA・AA・A の会社の運転者は、優良表示で優良乗り場に入れる' || char(10) || '令和7年度：対象280社のうち優良は269社（AAAは135社）' || char(10) || '■ 運転者の苦情・違反も会社の評価に響く', '一人ひとりの苦情が会社の評価を下げ、全員が優良乗り場に入れなくなることもあります。', '[]', '', '', 'タクシー評価制度｜https://www.tokyo-tc.or.jp/passenger/excellent-new/' || char(10) || '評価制度フロー（PDF）｜https://www.tokyo-tc.or.jp/driver/uploads/outline202504-202603.pdf');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 56, 'content', 'green', 'センターの街頭指導', '指導員とセンター指導協力員', 'センター職員と各社の管理者（指導協力員）が、深夜を中心に銀座・六本木・主要ターミナルで指導' || char(10) || '毎月「重点指導地区」と「特別公開指導」が発表される' || char(10) || '■ 令和8年10月：重点＝銀座・新橋、六本木／特別公開指導＝10月9日 新宿', '指導員に声をかけられたら素直に従いましょう。「指導無視」も違反になります。', '[]', '', '', '事業者・運転者の皆様（今月の指導）｜https://www.tokyo-tc.or.jp/driver/' || char(10) || 'センター指導協力員｜https://www.tokyo-tc.or.jp/driver/shidou/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 57, 'section', 'blue', '最新のお知らせ', '2026年10月時点', '', '', '[]', '', '', '');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 58, 'content', 'blue', '最近の大事な変更', 'ハンドブックより新しい情報', '令和8年4月20日：23区・武蔵野市・三鷹市の**運賃が改定**' || char(10) || '令和8年4月3日：優良乗り場に恵比寿駅西口前・北千住駅西口前を追加' || char(10) || '令和8年2月1日〜令和9年1月31日：羽田第3ターミナルの神奈川乗り場が休止' || char(10) || '令和8年10月6日〜：T-CAT優良乗り場の先頭が約10m後方へ' || char(10) || '麹町駅前タクシー乗り場が一時休止', 'お知らせは毎月出ます。月に一度は「お知らせ一覧」を開く習慣を。', '[]', '', '', '運賃改定のお知らせ｜https://www.tokyo-tc.or.jp/news/center/000196/' || char(10) || 'タクシー運賃料金表（東タク協）｜https://www.taxi-tokyo.or.jp/call/pricelist.html' || char(10) || '事業者・運転者のお知らせ一覧｜https://www.tokyo-tc.or.jp/news/driver/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 59, 'content', 'blue', 'イベント・工事の交通規制', 'お知らせ一覧に随時のる', '東京レガシーハーフマラソン2026' || char(10) || '東京湾大華火祭' || char(10) || '渋谷区 道玄坂・宮益坂の樹木工事' || char(10) || 'ワールドカップ パブリックビューイング開催時の走行注意' || char(10) || '■ 大きなイベントの日は、事前に規制を確認してから営業ルートを考える', '', '[]', '', '', '事業者・運転者のお知らせ一覧｜https://www.tokyo-tc.or.jp/news/driver/');
