INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '東京タクシーセンター 知識集' ORDER BY id DESC LIMIT 1), 61, 'content', 'slate', 'センターで買える教材', '2階 教務部窓口（平日9〜17時）・配送も可', '都内交通案内地図2026：3,600円（令和8年10月1日発行。事故危険箇所・冠水注意箇所つき）' || char(10) || '幹線道路・交差点図：130円（B2両面）' || char(10) || '銀座地区規制マップ：130円' || char(10) || '試験問題例集：930円' || char(10) || '英語でおもてなし講座DVD・英語/中国語の練習用CD', '都内交通案内地図は、車いすの乗降手順の動画QRも載っています。', '[]', '', '', '学習教材について｜https://www.tokyo-tc.or.jp/driver/training-dvd/');
