INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '知識集 まとめ（早見表）' ORDER BY id DESC LIMIT 1), 1, 'content', 'blue', '登録・運転者証', '早見表', '運転者証は前面ガラスの内側に表示（ないと営業できない）' || char(10) || '引っ越し・改姓・会社移動は届出が必要' || char(10) || '40日以上の免停・免許取消で登録は消える' || char(10) || '試験：45問中36問以上で合格、合格証は2年有効', '', '[]', '', '', '登録手続きについて｜https://www.tokyo-tc.or.jp/driver/register/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '知識集 まとめ（早見表）' ORDER BY id DESC LIMIT 1), 2, 'content', 'green', '研修', '早見表', '新人特別接遇研修：若い運転者向け（1日・2,200円）' || char(10) || '自主UD研修：車いす・高齢者・障がい者対応（火・木・金）' || char(10) || '外国人旅客接遇研修（英語）：修了で羽田おもてなしレーンへ' || char(10) || '英語検定合格（ECD）：羽田ECDレーン・東京駅の検定合格者レーンへ' || char(10) || '適正化研修：違反した人が受ける', '', '[]', '', '', '研修・検定について｜https://www.tokyo-tc.or.jp/driver/training/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '知識集 まとめ（早見表）' ORDER BY id DESC LIMIT 1), 3, 'stat', 'slate', '羽田空港', '早見表', '定額｜すべての乗り場が定額運賃乗り場' || char(10) || '奇数日｜は末尾奇数、偶数日は偶数（第5優良は除く）' || char(10) || '21番｜第5優良乗り場（第3ターミナル）', '', '[]', '', '', '羽田空港タクシー乗り場｜https://www.tokyo-tc.or.jp/driver/stand/haneda-stand/' || char(10) || '待機状況｜https://www.tokyo-tc.or.jp/driver/stand/livecamera/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '知識集 まとめ（早見表）' ORDER BY id DESC LIMIT 1), 4, 'content', 'slate', '乗り場', '早見表', '優良乗り場：15地区28か所（恵比寿・北千住が追加、渋谷西口・品川西口は休止）' || char(10) || '東京駅八重洲口：優良乗り場。第6レーンは検定合格者・ワゴン' || char(10) || 'EV・HV乗り場：新丸ビル前 平日9〜21時' || char(10) || '銀座：平日22時〜翌1時は乗り場以外で乗せない（リーフレット携行）' || char(10) || '六本木交差点：終日客待ち禁止', '', '[]', '', '', '乗り場案内｜https://www.tokyo-tc.or.jp/driver/stand/' || char(10) || '規制地区一覧｜https://www.tokyo-tc.or.jp/driver/regulation-area/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '知識集 まとめ（早見表）' ORDER BY id DESC LIMIT 1), 5, 'content', 'amber', '現場の声から', '早見表', '車内にいても駐車違反（霞が関・池袋・錦糸町）' || char(10) || '交差点・横断歩道・ロータリーに止めない' || char(10) || '待機所は休憩所ではない。あふれたら路上で待たない' || char(10) || '身障者用乗降スペースをふさがない・クラクションを鳴らさない' || char(10) || '喫煙は喫煙できる場所で、ごみは持ち帰る' || char(10) || '日本橋口・東京ステーションホテル車寄せで降ろさない', '', '[]', '', '', '情報提供｜https://www.tokyo-tc.or.jp/instance/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '知識集 まとめ（早見表）' ORDER BY id DESC LIMIT 1), 6, 'content', 'green', 'お客様対応', '早見表', '忘れ物：領収書の会社へ。分からなければ警察署・交番へ' || char(10) || '苦情：実名・匿名・善行のフォームがある' || char(10) || '優良運転者表彰：5年から。受賞で優良乗り場へ' || char(10) || '評価制度：会社の評価（AAA・AA・A）。苦情は会社の評価にも響く', '', '[]', '', '', '忘れ物｜https://www.tokyo-tc.or.jp/passenger/lostandfound/' || char(10) || '苦情・要望｜https://www.tokyo-tc.or.jp/passenger/complaint/' || char(10) || '表彰｜https://www.tokyo-tc.or.jp/driver/commend/');
INSERT INTO daihon_slides (deck_id, sort_order, layout, accent, title, subtitle, body, notes, images, ref_page, quiz, links) VALUES ((SELECT id FROM daihon_decks WHERE title = '知識集 まとめ（早見表）' ORDER BY id DESC LIMIT 1), 7, 'content', 'blue', '最新情報とリンク', '早見表', '令和8年4月20日 運賃改定' || char(10) || 'T-CAT優良乗り場 先頭を約10m後方へ（10月6日〜）' || char(10) || '毎月の重点指導地区は「事業者・運転者の皆様」ページに' || char(10) || '教材：都内交通案内地図2026（3,600円）', '', '[]', '', '', 'お知らせ一覧｜https://www.tokyo-tc.or.jp/news/driver/' || char(10) || '事業者・運転者の皆様｜https://www.tokyo-tc.or.jp/driver/' || char(10) || '教材｜https://www.tokyo-tc.or.jp/driver/training-dvd/');
